```typescript
import { Logger } from 'nestjs-pino';

@Controller()
export class AppController {
  constructor(private readonly myService: MyService, private readonly logger: Logger) {}

  @Get()
  getHello(): string {
    // pass message
    this.logger.log('getHello()');

