子模块状态管理： <https://nuxtjs.org/guide/vuex-store#modules-mode>

```js
// /store/todos.js
export const state = () => ({
  list: []
});

export const mutations = {
  add(store, text) {
    store.list.push({
      text,
      done: false
    });
  },
  remove(store, { todo }) {
    store.list.splice(store.list.indexOf(todo), 1);
  },
  toggle(store, todo) {
    // eslint-disable-next-line no-param-reassign
