(async () => {
  await receiver({
    connStr: 'test事件中心的连接',
    messageHandler: (msg) => {
      console.log('test');
      console.log(msg.body);
    }
  });
  await receiver({
    connStr: 'test2事件中心的连接',
    messageHandler: (msg) => {
      console.log('test2');
      console.log(msg.body);
    }
  });
})();
```

