创建数据库模型:

```js
const Sequelize = require('sequelize');

const Db = new Sequelize('数据库名', '用户名', '密码', {
  host: 'localhost',
  dialect: 'mysql'
});

const User = Db.define(
  'user',
  {
    uid: {
      type: Sequelize.INTEGER(11).UNSIGNED,
      allowNull: false,
      primaryKey: true
    },
    username: {
      type: Sequelize.STRING(16),
      allowNull: false,
      defaultValue: ''
    },
    mobile: {
      type: Sequelize.STRING(16),
      allowNull: false,
      defaultValue: ''
    },
    email: {
      type: Sequelize.STRING(32),
      allowNull: false,
      defaultValue: ''
    },
    password: {
      type: Sequelize.STRING(32),
      allowNull: false,
      defaultValue: ''
    },
    salt: {
      type: Sequelize.STRING(8),
      allowNull: false,
      defaultValue: ''
    }
  },
  {
    tableName: 'user',
    // 取消默认的时间戳, 否则会报 createdAt 不存在错误
    timestamps: false
  }
);

Db.sync();

module.exports = {
  Db,
  User
};
```

## `graphql-sequelize` 转换 MySQL -> GraphQL 结构

```js
const { GraphQLObjectType, GraphQLSchema, GraphQLList, GraphQLInt, GraphQLString } = require('graphql');
const { attributeFields, resolver } = require('graphql-sequelize');
const { Db, User } = require('./db');

userType = new GraphQLObjectType({
  name: 'User',
  description: 'A user',
  fields: attributeFields(User)
});

const Query = new GraphQLObjectType({
  name: 'Query',
  description: 'Root query object',
  fields: () => {
    return {
      user: {
        type: new GraphQLList(userType),
        args: {
          uid: {
            type: GraphQLInt
          },
          email: {
            type: GraphQLString
          }
        },
        resolve(root, args) {
          return Db.models.user.findAll({ where: args });
        }
      }
    };
  }
});

const Schema = new GraphQLSchema({
  query: Query
});

module.exports = Schema;
```

